"use strict";(self.webpackChunkdeep_notes=self.webpackChunkdeep_notes||[]).push([["19664"],{562417(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>h,frontMatter:()=>r,metadata:()=>i,toc:()=>d});var i=n(1956),a=n(474848),o=n(28453);let r={slug:"learning-prompt-examples",title:"Learning Prompt Examples",description:"Learning Prompt Examples",created:new Date("2026-06-24T00:00:00.000Z"),updated:new Date("2026-07-03T00:00:00.000Z")},s,l={},d=[{value:"Learn-fast prompt using the 80/20 principle to knowledge",id:"learn-fast-prompt-using-the-8020-principle-to-knowledge",level:2},{value:"Learning / Q&amp;A / Test / Interview",id:"learning--qa--test--interview",level:2},{value:"Interactive Voice Tests",id:"interactive-voice-tests",level:2},{value:"Create Test",id:"create-test",level:2},{value:"Speaking skills judge and feedback",id:"speaking-skills-judge-and-feedback",level:2},{value:"The learning curve destroyer",id:"the-learning-curve-destroyer",level:2},{value:"The real error simulator",id:"the-real-error-simulator",level:2},{value:"The impossible language translator",id:"the-impossible-language-translator",level:2},{value:"The personal learning path architect",id:"the-personal-learning-path-architect",level:2},{value:"The hidden gap detector",id:"the-hidden-gap-detector",level:2},{value:"The forced Feynman method",id:"the-forced-feynman-method",level:2}];function p(e){let t={a:"a",code:"code",h2:"h2",hr:"hr",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:(0,a.jsx)(t.a,{href:"https://www.reddit.com/r/ChatGPTPromptGenius/comments/1lp521t/you_can_learn_everything_with_this_prompt_best/",children:"You Can Learn Everything With This Prompt. BEST LEARNING PROMPT! : r/ChatGPTPromptGenius"})}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-markdown",children:'# *Information Gathering Prompt*\n\n---\n\n## *Prompt Input*\n- Enter the prompt topic = (......)\n- **The entered topic is a variable within curly braces that will be referred to as "M" throughout the prompt.**\n\n---\n\n## *Prompt Principles*\n- I am a researcher designing articles on various topics.\n- You are **absolutely not** supposed to help me design the article. (Most important point)\n	1. **Never suggest an article about "M" to me.**\n	2. **Do not provide any tips for designing an article about "M".**\n- You are only supposed to give me information about "M" so that **based on my learnings from this information, ==I myself== can go and design the article.**\n- In the "Prompt Output" section, various outputs will be designed, each labeled with a number, e.g., Output 1, Output 2, etc.\n	- **How the outputs work:**\n		1. **To start, after submitting this prompt, ask which output I need.**\n		2. I will type the number of the desired output, e.g., "1" or "2", etc.\n		3. You will only provide the output with that specific number.\n		4. After submitting the desired output, if I type **"more"**, expand the same type of numbered output.\n	- It doesn\u2019t matter which output you provide or if I type "more"; in any case, your response should be **extremely detailed** and use **the maximum characters and tokens** you can for the outputs. (Extremely important)\n- Thank you for your cooperation, respected chatbot!\n\n---\n\n## *Prompt Output*\n\n---\n\n### *Output 1*\n- This output is named: **"Basic Information"**\n- Includes the following:\n	- An **introduction** about "M"\n	- **General** information about "M"\n	- **Key** highlights and points about "M"\n- If "2" is typed, proceed to the next output.\n- If "more" is typed, expand this type of output.\n\n---\n\n### *Output 2*\n- This output is named: "Specialized Information"\n- Includes:\n	- More academic and specialized information\n	- If the prompt topic is character development:\n		- For fantasy character development, more detailed information such as hardcore fan opinions, detailed character stories, and spin-offs about the character.\n		- For real-life characters, more personal stories, habits, behaviors, and detailed information obtained about the character.\n- How to deliver the output:\n	1. Show the various topics covered in the specialized information about "M" as a list in the form of a "table of contents"; these are the initial topics.\n	2. Below it, type:\n		- "Which topic are you interested in?"\n			- If the name of the desired topic is typed, provide complete specialized information about that topic.\n		- "If you need more topics about \'M\', please type \'more\'"\n			- If "more" is typed, provide additional topics beyond the initial list. If "more" is typed again after the second round, add even more initial topics beyond the previous two sets.\n				- A note for you: When compiling the topics initially, try to include as many relevant topics as possible to minimize the need for using this option.\n		- "If you need access to subtopics of any topic, please type \'topics ... (desired topic)\'."\n			- If the specified text is typed, provide the subtopics (secondary topics) of the initial topics.\n			- Even if I type "topics ... (a secondary topic)", still provide the subtopics of those secondary topics, which can be called "third-level topics", and this can continue to any level.\n			- At any stage of the topics (initial, secondary, third-level, etc.), typing "more" will always expand the topics at that same level.\n		- **Summary**:\n			- If only the topic name is typed, provide specialized information in the format of that topic.\n			- If "topics ... (another topic)" is typed, address the subtopics of that topic.\n			- If "more" is typed after providing a list of topics, expand the topics at that same level.\n			- If "more" is typed after providing information on a topic, give more specialized information about that topic.\n	3. At any stage, if "1" is typed, refer to "Output 1".\n		- When providing a list of topics at any level, remind me that if I just type "1", we will return to "Basic Information"; if I type "option 1", we will go to the first item in that list.\n\n---\n==End==\n'})}),"\n",(0,a.jsx)(t.h2,{id:"learn-fast-prompt-using-the-8020-principle-to-knowledge",children:"Learn-fast prompt using the 80/20 principle to knowledge"}),"\n",(0,a.jsxs)(t.p,{children:["I want to learn about ",(0,a.jsx)(t.strong,{children:"insert_topic"}),". Identify and share the most important 20% of learnings from this topic that will help me understand 80% of it."]}),"\n",(0,a.jsx)(t.h2,{id:"learning--qa--test--interview",children:"Learning / Q&A / Test / Interview"}),"\n",(0,a.jsx)(t.p,{children:"I'm currently learning about snowflake. Ask me a series of 50 questions, one at a time, that will test my knowledge. Wait for my response before proceeding to the next question, ask the next question after your explanation of the answers. Identify knowledge gaps in my answers and give me better answers to fill those gaps. When finish show me the quantity of correct answers and the quantity of failed answers"}),"\n",(0,a.jsxs)(t.p,{children:["Assume role of a nutrition and training scientist. Use EBM SORT ( ",(0,a.jsx)(t.code,{children:"12<50%"})," ) to provide one word or one line answers to questions. (",(0,a.jsx)(t.code,{children:"<10 words"}),")."]}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"EBM - Evidence Based Method"}),"\n",(0,a.jsx)(t.li,{children:"SORT is a method for rating the strength of evidence in medical literature. It's part of Evidence-Based Medicine (EBM), which is a way of making patient care decisions using the best available evidence."}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"interactive-voice-tests",children:"Interactive Voice Tests"}),"\n",(0,a.jsx)(t.p,{children:"Start playing trivia speaking games with gemini."}),"\n",(0,a.jsx)(t.p,{children:"Let's play a game, you will ask me a question I will answer, you will give me a number based on the quality of answer, and give the right answers and then ask next question"}),"\n",(0,a.jsx)(t.p,{children:"Until I say speak, don't respond, since I can take few pauses in between, so let me finish and cue that I have finished is when I explicitly tell to speak"}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsxs)(t.p,{children:["You are my personal tutor in ",(0,a.jsx)(t.code,{children:"{subject}"}),". We are going to have an interactive voice-based learning session where you will ask me a question, wait for my answer, analyze my response, and then provide constructive feedback. If my answer is incorrect or incomplete, explain where I went wrong and provide the correct answer before moving on to the next question. Keep the conversation engaging, adaptive, and based on my learning pace. Ensure the questions gradually increase in difficulty based on my performance. Let\u2019s begin!"]}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Take a pause before answering, since I speak slow"}),"\n",(0,a.jsx)(t.li,{children:"Quiz me about advanced biology concepts"}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"create-test",children:"Create Test"}),"\n",(0,a.jsx)(t.p,{children:"Create 30 MCQ (with 4 options each and 1 correct answer) for a finance intern for a 40 min test. The finance intern should have below skills"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Ability to decode RBI guidelines"}),"\n",(0,a.jsx)(t.li,{children:"Proficiency in crafting easily understandable directives for tech teams"}),"\n",(0,a.jsx)(t.li,{children:"Previous IT experience is a plus"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Questions should also focus on compliances, audits. Add 10 aptitude and logical reasoning questions. Add 5 data analytics using tables questions. Other 15 questions should be around - Certified banking compliance professional program."}),"\n",(0,a.jsx)(t.p,{children:"Make sure to"}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"don't mention finance intern anywhere"}),"\n",(0,a.jsx)(t.li,{children:"questions should be direct and with medium difficulty, the given questions are very easy and novice"}),"\n",(0,a.jsx)(t.li,{children:"Share all 30 questions"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Create 15 mcq questions (with 4 options each and 1 correct answer) around below topics"}),"\n",(0,a.jsx)(t.h2,{id:"speaking-skills-judge-and-feedback",children:"Speaking skills judge and feedback"}),"\n",(0,a.jsx)(t.p,{children:"Hi ChatGPT, I'm speaking this prompt aloud, and I know it might not sound perfect\u2014but please don\u2019t judge me based on how I say it. I'm here to improve my impromptu speaking and extempore skills. I'd like you to ask me a series of thoughtful questions or give me topics that can help you analyze how I think and respond on the spot. After that, I'd really appreciate feedback on where I can improve\u2014whether it's my structure, clarity, confidence, or vocabulary\u2014so I can gradually get better at speaking off the cuff. Let's begin whenever you're ready!"}),"\n",(0,a.jsx)(t.h2,{id:"the-learning-curve-destroyer",children:"The learning curve destroyer"}),"\n",(0,a.jsx)(t.p,{children:"You are a teacher who has only 4 hours with me and will never see me again. Your only objective is to make me functional in [SKILL] before the time runs out."}),"\n",(0,a.jsx)(t.p,{children:"No theory without practical use, and no generic lists."}),"\n",(0,a.jsx)(t.p,{children:"Tell me three things: what to learn first, what to ignore completely, and the one exercise that, done a single time, would already put me ahead of 70% of people who have studied this for months."}),"\n",(0,a.jsx)(t.p,{children:"Teach me the first step, then wait for my reply."}),"\n",(0,a.jsx)(t.h2,{id:"the-real-error-simulator",children:"The real error simulator"}),"\n",(0,a.jsx)(t.p,{children:"Do not explain [CONCEPT] to me."}),"\n",(0,a.jsx)(t.p,{children:"Put me directly into a realistic situation where I would have to use it and would probably make a mistake. Then wait for my response."}),"\n",(0,a.jsx)(t.p,{children:"When I make a mistake, do not give me the answer. Ask me one question that forces me to find where my reasoning breaks."}),"\n",(0,a.jsx)(t.p,{children:"Give me the answer only after I have tried at least twice. Then repeat the cycle with a new situation until I can get it right without hesitation."}),"\n",(0,a.jsx)(t.h2,{id:"the-impossible-language-translator",children:"The impossible language translator"}),"\n",(0,a.jsx)(t.p,{children:"The content below is confusing to me."}),"\n",(0,a.jsx)(t.p,{children:"Before explaining anything, tell me the one core idea that, once I understand it, makes the rest fall into place."}),"\n",(0,a.jsx)(t.p,{children:"Explain only that idea first, using an everyday analogy and no technical terms."}),"\n",(0,a.jsx)(t.p,{children:"Then ask me 3 questions that only someone who truly understood it could answer. Ask them one at a time and wait for my answers."}),"\n",(0,a.jsx)(t.p,{children:"Do not move on to the rest until I pass all three."}),"\n",(0,a.jsx)(t.p,{children:"[PASTE THE CONTENT HERE]"}),"\n",(0,a.jsx)(t.h2,{id:"the-personal-learning-path-architect",children:"The personal learning path architect"}),"\n",(0,a.jsx)(t.p,{children:"My real goal is [GOAL]."}),"\n",(0,a.jsx)(t.p,{children:"It is not to learn [SKILL] in general. It is to achieve [SPECIFIC RESULT] within [DEADLINE]."}),"\n",(0,a.jsx)(t.p,{children:"I already know [WHAT YOU ALREADY MASTER]."}),"\n",(0,a.jsx)(t.p,{children:"Based on that, build me a 7-day learning path."}),"\n",(0,a.jsx)(t.p,{children:"Each day must include: one single task that fits within 45 minutes, a clear criterion so I know whether I did it correctly, and what not to do that day so I do not waste time."}),"\n",(0,a.jsx)(t.p,{children:"If the path won\u2019t get me there, rebuild it."}),"\n",(0,a.jsx)(t.h2,{id:"the-hidden-gap-detector",children:"The hidden gap detector"}),"\n",(0,a.jsx)(t.p,{children:"I think I already master [SKILL]. I want you to prove me wrong."}),"\n",(0,a.jsx)(t.p,{children:"Ask me 5 questions that seem simple but expose the gaps of someone who has never truly gone deep."}),"\n",(0,a.jsx)(t.p,{children:"Ask them one at a time and wait for each answer."}),"\n",(0,a.jsx)(t.p,{children:"After every answer, tell me what it reveals about what is still missing in my foundation."}),"\n",(0,a.jsx)(t.p,{children:"Do not go easy on me. If I am being shallow, tell me directly."}),"\n",(0,a.jsx)(t.h2,{id:"the-forced-feynman-method",children:"The forced Feynman method"}),"\n",(0,a.jsx)(t.p,{children:"I just studied [TOPIC]."}),"\n",(0,a.jsx)(t.p,{children:"I am going to explain what I understood as if you were a 10-year-old child."}),"\n",(0,a.jsx)(t.p,{children:"Wait for my explanation. While I explain, stop me every time I use jargon I cannot define, skip a step in the reasoning, or simplify so much that it becomes wrong."}),"\n",(0,a.jsx)(t.p,{children:"At the end, tell me exactly what those mistakes reveal about what is still not solid in my understanding."})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(p,{...e})}):p(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(296540);let a={},o=i.createContext(a);function r(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(o.Provider,{value:t},e.children)}},1956(e){e.exports=JSON.parse('{"id":"ai/llm/prompting/learning-prompt-examples","title":"Learning Prompt Examples","description":"Learning Prompt Examples","source":"@site/docs/ai/llm/prompting/learning-prompt-examples.md","sourceDirName":"ai/llm/prompting","slug":"/ai/llm/prompting/learning-prompt-examples","permalink":"/ai/llm/prompting/learning-prompt-examples","draft":false,"unlisted":false,"editUrl":"https://github.com/deepaksood619/deepaksood619.github.io/tree/master/docs/ai/llm/prompting/learning-prompt-examples.md","tags":[],"version":"current","lastUpdatedBy":"Deepak Sood","lastUpdatedAt":1783144265000,"frontMatter":{"slug":"learning-prompt-examples","title":"Learning Prompt Examples","description":"Learning Prompt Examples","created":"2026-06-24T00:00:00.000Z","updated":"2026-07-03T00:00:00.000Z"},"sidebar":"tutorialSidebar","previous":{"title":"Context Engineering","permalink":"/ai/llm/prompting/context-engineering"},"next":{"title":"Lovable Prompt Portfolio Website","permalink":"/ai/llm/prompting/lovable-prompt-portfolio-website"}}')}}]);